import pandas as pd


def run(inputs: dict) -> dict:
    dim = inputs["dim_account"].copy()
    stg = inputs["stg_account"].copy()

    # Build per-account list of mutable version dicts from the existing dimension.
    account_versions = {}
    for _, row in dim.iterrows():
        aid = row["account_id"]
        version = {
            "plan": row["plan"],
            "eff_start_date": row["eff_start_date"],
            "eff_end_date": row["eff_end_date"],
            "is_current": row["is_current"],
        }
        account_versions.setdefault(aid, []).append(version)

    # Process staged records in (account_id, update_date) order; each sees
    # the effects of earlier ones because we mutate account_versions in place.
    stg_sorted = stg.sort_values(["account_id", "update_date"], kind="stable")

    def plans_equal(a, b):
        a_na = pd.isna(a)
        b_na = pd.isna(b)
        if a_na and b_na:
            return True
        if a_na != b_na:
            return False
        return a == b

    for _, s in stg_sorted.iterrows():
        aid = s["account_id"]
        plan = s["plan"]
        d = s["update_date"]

        versions = account_versions.setdefault(aid, [])

        if not versions:
            versions.append({
                "plan": plan,
                "eff_start_date": d,
                "eff_end_date": pd.NaT,
                "is_current": 1,
            })
            continue

        # Find the version covering d: start <= d < end (end NULL = open/infinite).
        covering = None
        for v in versions:
            start = v["eff_start_date"]
            end = v["eff_end_date"]
            if start <= d and (pd.isna(end) or d < end):
                covering = v
                break

        if covering is None:
            # d is earlier than the account's earliest version.
            f = min(versions, key=lambda v: v["eff_start_date"])
            versions.append({
                "plan": plan,
                "eff_start_date": d,
                "eff_end_date": f["eff_start_date"],
                "is_current": 0,
            })
        else:
            v = covering
            if plans_equal(v["plan"], plan):
                # no-op
                continue
            elif d == v["eff_start_date"]:
                # same-day correction, no new version
                v["plan"] = plan
            else:
                # split v at d
                versions.append({
                    "plan": plan,
                    "eff_start_date": d,
                    "eff_end_date": v["eff_end_date"],
                    "is_current": v["is_current"],
                })
                v["eff_end_date"] = d
                v["is_current"] = 0

    # Flatten result.
    rows = []
    for aid, versions in account_versions.items():
        for v in versions:
            rows.append({
                "account_id": aid,
                "plan": v["plan"],
                "eff_start_date": v["eff_start_date"],
                "eff_end_date": v["eff_end_date"],
                "is_current": v["is_current"],
            })

    out = pd.DataFrame(
        rows,
        columns=["account_id", "plan", "eff_start_date", "eff_end_date", "is_current"],
    )

    if not out.empty:
        out = out.sort_values(["account_id", "eff_start_date"]).reset_index(drop=True)

    out["account_id"] = out["account_id"].astype("int64")
    out["is_current"] = out["is_current"].astype("int64")
    out["eff_start_date"] = pd.to_datetime(out["eff_start_date"])
    out["eff_end_date"] = pd.to_datetime(out["eff_end_date"])

    return {"dim_account_out": out}
